import { Button } from '@refy-design/web';
import { PlanCard } from '@refy-design/web';
import type { ComponentProps } from 'react';
const starterFeatures = [
  <span key="1">
    <strong>800 credits</strong> per month
  </span>,
  '1 member · 5 projects',
  'Standard analysis, rerun, recommendations',
  'Basic activity history',
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof PlanCard>,
    'name' | 'price' | 'period' | 'priceNote' | 'features' | 'cta'
  > = {
    name: 'Starter',
    price: 'R$ 79',
    period: '/mo',
    priceNote: 'R$ 948 billed yearly',
    features: starterFeatures,
    cta: (
      <Button variant="secondary" block>
        Switch to Starter
      </Button>
    ),
  };
  return (
    <div style={{ maxWidth: 260 }}>
      <PlanCard {...args} />
    </div>
  );
}

