import { Button } from '@refy-design/web';
import { PlanCard } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function PlanCardExample() {
  const [selected, setSelected] = useState('Essential');
  return (
    <div style={stack}>
      <p>Local plan choice, no charge.</p>
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit,minmax(min(100%,220px),1fr))',
          gap: 16,
        }}
      >
        {['Essential', 'Team'].map((name, i) => (
          <PlanCard
            key={name}
            name={name}
            price={i ? 'R$ 199' : 'R$ 79'}
            period="/mo"
            features={
              i
                ? ['Up to 10 members', 'Shared projects']
                : ['1 member', 'Personal projects']
            }
            current={selected === name}
            cta={<Button onClick={() => setSelected(name)}>Choose {name}</Button>}
          />
        ))}
      </div>
      <p role="status">Selected plan: {selected}</p>
    </div>
  );
}
export function Example() {
  return <PlanCardExample />;
}
